def fusionner(ref: dict, enrichissements: list[tuple[str, dict]]) -> dict:
    resultat = dict(ref)
    origine = {k: "tmdb" for k, v in ref.items() if v is not None}
    for nom_source, donnees in enrichissements:          # déjà triées par priorité
        for champ, valeur in donnees.items():
            if resultat.get(champ) is None and valeur is not None:
                resultat[champ] = valeur
                origine[champ] = nom_source
    resultat["origine"] = origine
    return resultat

film = fusionner({"titre": "Alien", "synopsis": None},
                 [("rotten", {"tomatometer": 98}), ("kaggle", {"synopsis": "Dans l'espace…"})])
print(film["origine"])   # {'titre': 'tmdb', 'tomatometer': 'rotten', 'synopsis': 'kaggle'}
